package runcontrol

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
	"time"
)

const (
	LocalLogRelativePath = ".ultraplan/run-control.log"
	MaxLocalLogBytes     = int64(1 << 20)
	maxLocalLogLineBytes = 4 << 10
)

type LocalLogRecord struct {
	At      time.Time         `json:"at"`
	Level   LogLevel          `json:"level"`
	Message string            `json:"message"`
	Fields  map[string]string `json:"fields,omitempty"`
}

// LocalFileLogger is a bounded, private, append-only diagnostic sink. Each
// process writes one JSON record with one O_APPEND write; reaching the bound
// drops later diagnostic records rather than consuming reserved DB headroom.
type LocalFileLogger struct {
	mu   sync.Mutex
	file *os.File
}

func OpenLocalFileLogger(workspaceRoot string) (*LocalFileLogger, error) {
	root, err := validateWorkspaceRoot(workspaceRoot)
	if err != nil {
		return nil, err
	}
	directory := filepath.Join(root, ".ultraplan")
	info, err := os.Lstat(directory)
	if err != nil {
		return nil, classifyStoreError("open_local_log", "inspect private run-control directory failed", err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return nil, invalidField("run_control_directory", "must be a real directory, not a symlink")
	}
	path := filepath.Join(root, filepath.FromSlash(LocalLogRelativePath))
	if info, err := os.Lstat(path); err == nil {
		if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
			return nil, invalidField("run_control_log", "must be a regular file, not a symlink")
		}
	} else if !errors.Is(err, fs.ErrNotExist) {
		return nil, classifyStoreError("open_local_log", "inspect private run-control log failed", err)
	}
	file, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		return nil, classifyStoreError("open_local_log", "open private run-control log failed", err)
	}
	if err := enforcePrivateMode(path, 0o600); err != nil {
		_ = file.Close()
		return nil, err
	}
	return &LocalFileLogger{file: file}, nil
}

func (l *LocalFileLogger) Log(_ context.Context, level LogLevel, message string, fields ...LogField) {
	if l == nil || l.file == nil {
		return
	}
	record := LocalLogRecord{At: time.Now().UTC(), Level: level, Message: safeEventValue(message, 256), Fields: make(map[string]string)}
	for _, field := range fields {
		key := safeEventValue(field.Key, 64)
		if key == "" || sensitiveEventField(key) {
			continue
		}
		value := field.Value
		if unsafeEventValue(value) || len(value) > MaxSafeValueBytes {
			value = "[omitted]"
		}
		record.Fields[key] = safeEventValue(value, MaxSafeValueBytes)
	}
	encoded, err := json.Marshal(record)
	if err != nil || len(encoded)+1 > maxLocalLogLineBytes {
		return
	}
	encoded = append(encoded, '\n')
	l.mu.Lock()
	defer l.mu.Unlock()
	info, err := l.file.Stat()
	if err != nil || info.Size()+int64(len(encoded)) > MaxLocalLogBytes {
		return
	}
	_, _ = l.file.Write(encoded)
}

func (l *LocalFileLogger) Close() error {
	if l == nil {
		return nil
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.file == nil {
		return nil
	}
	err := l.file.Close()
	l.file = nil
	return err
}

func ReadLocalLogs(workspaceRoot string, limit int) ([]LocalLogRecord, error) {
	if limit < 1 || limit > 500 {
		return nil, invalidField("local_log.limit", "must be between 1 and 500")
	}
	root, err := validateWorkspaceRoot(workspaceRoot)
	if err != nil {
		return nil, err
	}
	path := filepath.Join(root, filepath.FromSlash(LocalLogRelativePath))
	info, err := os.Lstat(path)
	if errors.Is(err, fs.ErrNotExist) {
		return []LocalLogRecord{}, nil
	}
	if err != nil {
		return nil, classifyStoreError("read_local_log", "inspect private run-control log failed", err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() || info.Size() > MaxLocalLogBytes {
		return nil, wrapError(CodeCorrupt, "read_local_log", "private run-control log violates its bounded regular-file contract", false, nil)
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, classifyStoreError("read_local_log", "open private run-control log failed", err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(io.LimitReader(file, MaxLocalLogBytes+1))
	scanner.Buffer(make([]byte, 1024), maxLocalLogLineBytes)
	records := make([]LocalLogRecord, 0, limit)
	for scanner.Scan() {
		var record LocalLogRecord
		if json.Unmarshal(scanner.Bytes(), &record) != nil || record.At.IsZero() || record.Message == "" {
			continue
		}
		if len(records) == limit {
			copy(records, records[1:])
			records = records[:limit-1]
		}
		records = append(records, record)
	}
	if err := scanner.Err(); err != nil {
		return nil, classifyStoreError("read_local_log", "read private run-control log failed", err)
	}
	return records, nil
}

package runcontrol

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"time"
)

var allowedEventPayloadFields = map[string]struct{}{
	"runtime_event_id": {}, "runtime_run_id": {}, "agentwrap_run_id": {}, "session_id": {},
	"external_harness_run_id": {}, "type": {}, "kind": {}, "state": {}, "status": {},
	"outcome": {}, "reason": {}, "category": {}, "code": {}, "count": {}, "known": {},
	"input_tokens": {}, "output_tokens": {}, "total_tokens": {}, "turns": {},
	"artifact_kind": {}, "artifact_id": {}, "lifecycle": {}, "liveness": {},
	"message": {}, "index": {}, "scope": {}, "tool": {}, "action": {}, "detail": {},
	"tool_call_id": {}, "tool_name": {}, "tool_status": {}, "tool_arguments": {},
	"tool_result": {}, "tool_error": {},
	"provider": {}, "model": {}, "harness": {},
	"phase_state": {}, "summary": {},
}

// sanitizeEventDraft is the final storage gate. Producers may only submit
// bounded product-owned fields; raw payloads, prompts, arbitrary diagnostics,
// credentials, and unrestricted paths are replaced with explicit omission.
func sanitizeEventDraft(input EventDraft) EventDraft {
	out := EventDraft{
		Type: input.Type, Scope: input.Scope, Stage: safeEventValue(input.Stage, MaxTargetFieldBytes),
		Task: safeEventValue(input.Task, MaxTargetFieldBytes), Kind: safeEventValue(input.Kind, MaxSafeValueBytes),
		Tool: safeEventValue(input.Tool, MaxSafeValueBytes), Action: safeEventValue(input.Action, MaxSafeValueBytes),
		Reason: safeEventValue(input.Reason, MaxSafeValueBytes), Detail: safeEventValue(input.Detail, MaxSafeValueBytes), Lifecycle: input.Lifecycle,
		Payload: make(map[string]string), Omission: cloneOmission(input.Omission),
	}
	omitted := uint64(0)
	for key, value := range input.Payload {
		if _, ok := allowedEventPayloadFields[key]; !ok || sensitiveEventField(key) || unsafeEventValue(value) {
			omitted++
			continue
		}
		if len(value) > MaxSafeValueBytes {
			omitted++
			continue
		}
		out.Payload[key] = safeEventValue(value, MaxSafeValueBytes)
	}
	if out.Stage != input.Stage || out.Task != input.Task {
		omitted++
	}
	if omitted > 0 {
		mergeOmission(&out, "unsafe event detail omitted", omitted, nil, nil)
	}
	encoded, err := json.Marshal(out)
	if err != nil || len(encoded) > MaxEncodedEventBytes {
		return EventDraft{
			Type:     EventWarning,
			Payload:  map[string]string{"code": "event_detail_oversize", "reason": "event detail exceeded durable limit"},
			Omission: &Omission{Reason: "oversize event detail omitted", Count: max(omitted, 1)},
		}
	}
	return out
}

func mergeOmission(draft *EventDraft, reason string, count uint64, first, last *time.Time) {
	if draft.Omission == nil {
		draft.Omission = &Omission{Reason: reason, Count: count, FirstAt: first, LastAt: last}
		return
	}
	draft.Omission.Count += count
	if draft.Omission.Reason == "" {
		draft.Omission.Reason = reason
	}
	if draft.Omission.FirstAt == nil {
		draft.Omission.FirstAt = first
	}
	if last != nil {
		draft.Omission.LastAt = last
	}
}

func sensitiveEventField(key string) bool {
	key = strings.ToLower(key)
	for _, fragment := range []string{"secret", "token", "credential", "password", "prompt", "payload", "stdout", "stderr", "path", "command"} {
		if strings.Contains(key, fragment) {
			return true
		}
	}
	return false
}

func unsafeEventValue(value string) bool {
	lower := strings.ToLower(strings.TrimSpace(value))
	if strings.ContainsAny(value, "\x00\r\n") || filepath.IsAbs(value) {
		return true
	}
	if len(value) >= 3 && value[1] == ':' && (value[2] == '\\' || value[2] == '/') {
		return true
	}
	for _, marker := range []string{"bearer ", "sk-", "ghp_", "github_pat_", "-----begin private key"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

func safeEventValue(value string, limit int) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > limit {
		value = value[:limit]
	}
	return value
}

package runcontrol

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

const (
	DatabaseRelativePath = ".ultraplan/run-control.db"
	BusyTimeout          = 5 * time.Second
	defaultMaxOpenConns  = 4
	maxOpenConns         = 16
	defaultEventPage     = 200
	maxEventPage         = 512
)

// SQLiteOptions controls process-local seams and connection bounds. Durable
// safety pragmas are fixed product invariants and cannot be weakened here.
type SQLiteOptions struct {
	Clock        Clock
	IDs          IDSource
	Logger       Logger
	Notifier     Notifier
	MaxOpenConns int
	Retention    RetentionPolicy
}

// SQLiteRepository is a direct multi-process repository over one workspace
// database. Every mutation uses a short immediate transaction.
type SQLiteRepository struct {
	db            *sql.DB
	path          string
	clock         Clock
	clockInjected bool
	ids           IDSource
	loggerMu      sync.RWMutex
	logger        Logger
	notifier      Notifier
	retention     RetentionPolicy
	softQuota     int64
	metrics       repositoryMetrics
}

var _ Repository = (*SQLiteRepository)(nil)

// OpenSQLite opens or creates the private workspace run-control database.
func OpenSQLite(ctx context.Context, workspaceRoot string, opts SQLiteOptions) (*SQLiteRepository, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	root, err := validateWorkspaceRoot(workspaceRoot)
	if err != nil {
		return nil, err
	}
	databasePath, err := preparePrivateDatabase(root)
	if err != nil {
		return nil, err
	}

	values := url.Values{}
	values.Set("_busy_timeout", strconv.FormatInt(BusyTimeout.Milliseconds(), 10))
	values.Set("_foreign_keys", "on")
	values.Set("_journal_mode", "WAL")
	values.Set("_synchronous", "FULL")
	values.Set("_txlock", "immediate")
	values.Set("_defensive", "1")
	dsn := (&url.URL{Scheme: "file", Path: filepath.ToSlash(databasePath), RawQuery: values.Encode()}).String()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, classifyStoreError("open", "open run-control database failed", err)
	}
	closeOnError := true
	defer func() {
		if closeOnError {
			_ = db.Close()
		}
	}()

	connections := opts.MaxOpenConns
	if connections == 0 {
		connections = defaultMaxOpenConns
	}
	if connections < 1 || connections > maxOpenConns {
		return nil, invalidField("max_open_connections", fmt.Sprintf("must be between 1 and %d", maxOpenConns))
	}
	db.SetMaxOpenConns(connections)
	db.SetMaxIdleConns(connections)
	if err := db.PingContext(ctx); err != nil {
		return nil, classifyStoreError("ping", "run-control database is unavailable", err)
	}
	if err := verifyPragmas(ctx, db); err != nil {
		return nil, err
	}
	clock := opts.Clock
	clockInjected := clock != nil
	if clock == nil {
		clock = WallClock{}
	}
	if err := migrateSchema(ctx, db, databasePath, clock); err != nil {
		return nil, err
	}
	if err := enforcePrivateMode(databasePath, 0o600); err != nil {
		return nil, err
	}

	ids := opts.IDs
	if ids == nil {
		ids = RandomIDSource{}
	}
	retention, err := normalizeRetentionPolicy(opts.Retention)
	if err != nil {
		return nil, err
	}
	repository := &SQLiteRepository{
		db: db, path: databasePath, clock: clock, clockInjected: clockInjected, ids: ids,
		logger: opts.Logger, notifier: opts.Notifier,
		retention: retention, softQuota: retention.HardQuotaBytes - ReservedHeadroomBytes,
	}
	closeOnError = false
	return repository, nil
}

func validateWorkspaceRoot(workspaceRoot string) (string, error) {
	if strings.TrimSpace(workspaceRoot) == "" {
		return "", invalidField("workspace_root", "is required")
	}
	root, err := filepath.Abs(workspaceRoot)
	if err != nil {
		return "", wrapError(CodeInvalidArgument, "resolve_workspace", "workspace root is invalid", false, err)
	}
	info, err := os.Stat(root)
	if err != nil {
		return "", classifyStoreError("stat_workspace", "workspace root cannot be inspected", err)
	}
	if !info.IsDir() {
		return "", invalidField("workspace_root", "must be a directory")
	}
	return filepath.Clean(root), nil
}

func preparePrivateDatabase(root string) (string, error) {
	directory := filepath.Join(root, ".ultraplan")
	info, err := os.Lstat(directory)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		if err := os.Mkdir(directory, 0o700); err != nil {
			return "", classifyStoreError("create_directory", "create private run-control directory failed", err)
		}
	case err != nil:
		return "", classifyStoreError("inspect_directory", "inspect run-control directory failed", err)
	case info.Mode()&os.ModeSymlink != 0 || !info.IsDir():
		return "", invalidField("run_control_directory", "must be a real directory, not a symlink")
	}
	if err := enforcePrivateMode(directory, 0o700); err != nil {
		return "", err
	}

	path := filepath.Join(directory, "run-control.db")
	info, err = os.Lstat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		file, createErr := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_RDWR, 0o600)
		if createErr != nil {
			return "", classifyStoreError("create_database", "create private run-control database failed", createErr)
		}
		if closeErr := file.Close(); closeErr != nil {
			return "", classifyStoreError("close_database", "close new run-control database failed", closeErr)
		}
	case err != nil:
		return "", classifyStoreError("inspect_database", "inspect run-control database failed", err)
	case info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular():
		return "", invalidField("run_control_database", "must be a regular file, not a symlink")
	}
	if err := enforcePrivateMode(path, 0o600); err != nil {
		return "", err
	}
	return path, nil
}

func enforcePrivateMode(path string, want fs.FileMode) error {
	if err := os.Chmod(path, want); err != nil {
		return classifyStoreError("set_permissions", "set private run-control permissions failed", err)
	}
	info, err := os.Stat(path)
	if err != nil {
		return classifyStoreError("verify_permissions", "verify run-control permissions failed", err)
	}
	if got := info.Mode().Perm(); got != want {
		return wrapError(CodePermission, "verify_permissions", fmt.Sprintf("private permissions are %04o; require %04o", got, want), false, nil)
	}
	return nil
}

func verifyPragmas(ctx context.Context, db *sql.DB) error {
	checks := []struct {
		name string
		want string
	}{
		{name: "journal_mode", want: "wal"},
		{name: "synchronous", want: "2"},
		{name: "foreign_keys", want: "1"},
		{name: "busy_timeout", want: "5000"},
	}
	for _, check := range checks {
		var got string
		if err := db.QueryRowContext(ctx, "PRAGMA "+check.name).Scan(&got); err != nil {
			return classifyStoreError("verify_pragma", "verify required SQLite durability policy failed", err)
		}
		if !strings.EqualFold(got, check.want) {
			return wrapError(CodeInvariant, "verify_pragma", fmt.Sprintf("SQLite %s=%s; require %s", check.name, got, check.want), false, nil)
		}
	}
	return nil
}

const initialSchema = `
CREATE TABLE IF NOT EXISTS app_schema (
